using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
namespace FishSandbox {
 [Serializable] public class CatchData {public string species;public float weight;public bool drip,cooked;public int price;}
 [Serializable] public class SaveData {public int coins,bait,landed;public List<CatchData> bag=new();}
 public enum FishingState {Idle,Waiting,Biting,Reeling}
 public class FishingGame : MonoBehaviour {
  public static FishingGame Instance; public HarborWorld world;public Camera cam; public CharacterController body;public GiftEngine gifts;public GiftPanel ui;public readonly List<CatchData> bag=new();public readonly List<WorldEntity> entities=new();
  public float health=100,fullness=100,yaw,pitch,vertical,lineProgress,tension,biteAt,biteDeadline;public int coins=100,bait=10,ammo=12,landed,tool;public bool driving,dead,testing;public FishingState fishing;
  public int nextDrip,nextHeavy,nextSale,lineGuard,quickBite,slowBite;public float nextWeight=3,nextPayout=2,nextDelay=2;public float boatSpeed=>gifts.Value("boat/speed_boost");
  public readonly Queue<GiftSegment> biteQueue=new();
  public void ClearPendingGifts(){biteQueue.Clear();nextDrip=nextHeavy=nextSale=lineGuard=quickBite=slowBite=0;}
  void ArmBite(GiftSegment segment){for(int i=0;i<segment.count;i++){biteQueue.Enqueue(segment);if(segment.gift.id=="fishing/quick_bite")quickBite++;else slowBite++;}if(fishing==FishingState.Waiting){float wait=Mathf.Max(1,biteAt-Time.time);ConsumeBite(ref wait);biteAt=Time.time+wait;}}
  void ConsumeBite(ref float wait){if(biteQueue.Count>0){var s=biteQueue.Dequeue();if(s.gift.id=="fishing/quick_bite"){quickBite=Mathf.Max(0,quickBite-1);wait=.15f;}else{slowBite=Mathf.Max(0,slowBite-1);wait*=Mathf.Clamp(s.value,1,3);}}else if(quickBite>0){quickBite--;wait=.15f;}else if(slowBite>0){slowBite--;wait*=nextDelay;}}
  public Vector3 impulse,automationMove;public Transform rod,gun,floatBobber,heldVisual;public LineRenderer line;public CatchData held;public string notification="欢迎来到群岛。沿码头前行，抛竿试试！";public float notifyUntil;public WorldEntity boss;public int shotCount;public Vector3 lastShotDirection;
  float statusTick,saveTick,shotAt;AudioSource audioSource;AudioClip pop,castSound;Vector3 spawn=new(0,1.35f,21); readonly string[] species={"Cod","Shark","Seahorse","GameName","Dripper","LemonSole","Pike","Mackerel","Triggerfish","Eel","Gar"};
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(Instance==null)new GameObject("FishingGame").AddComponent<FishingGame>();}
  void Awake(){Instance=this;testing=Array.Exists(Environment.GetCommandLineArgs(),x=>x=="-fish-selftest");world=gameObject.AddComponent<HarborWorld>();world.Generate();gifts=new GiftEngine(this);CreatePlayer();CreateTools();ui=gameObject.AddComponent<GiftPanel>();ui.game=this;gameObject.AddComponent<LocalGiftBridge>();audioSource=gameObject.AddComponent<AudioSource>();pop=Tone(660,.1f);castSound=Tone(220,.18f);if(!testing)Load();if(testing)gameObject.AddComponent<SandboxVerification>();}
  AudioClip Tone(float frequency,float seconds){int n=(int)(44100*seconds);var samples=new float[n];for(int i=0;i<n;i++)samples[i]=Mathf.Sin(i*frequency*2*Mathf.PI/44100)*.12f*(1-i/(float)n);var clip=AudioClip.Create("Tone",n,1,44100,false);clip.SetData(samples,0);return clip;}
  void Sound(AudioClip c){if(audioSource&&c)audioSource.PlayOneShot(c);}
  void CreatePlayer(){var player=new GameObject("Player");player.transform.position=spawn;body=player.AddComponent<CharacterController>();body.height=1.8f;body.radius=.32f;body.center=new Vector3(0,.9f,0);body.stepOffset=.35f;cam=new GameObject("View").AddComponent<Camera>();cam.transform.SetParent(player.transform,false);cam.transform.localPosition=new Vector3(0,1.62f,0);cam.nearClipPlane=.08f;cam.farClipPlane=500;cam.fieldOfView=72;cam.backgroundColor=new Color(.55f,.75f,.83f);cam.clearFlags=CameraClearFlags.Skybox;cam.gameObject.AddComponent<AudioListener>();}
  void CreateTools(){rod=world.Root("Fishing rod",new Vector3(.43f,-.36f,.55f),cam.transform);var handle=world.Box("Grip",Vector3.zero,new Vector3(.055f,.055f,.5f),HarborWorld.Wood,rod,false);var shaft=world.Box("Rod blank",new Vector3(0,.28f,.95f),new Vector3(.028f,.028f,2.1f),new Color(.12f,.18f,.19f),rod,false);shaft.transform.localRotation=Quaternion.Euler(-16,0,0);world.Shape("Reel",PrimitiveType.Cylinder,new Vector3(0,-.08f,.15f),new Vector3(.18f,.07f,.18f),HarborWorld.Gold,rod,false);gun=world.Root("Rifle",new Vector3(.34f,-.3f,.55f),cam.transform);world.Box("Body",Vector3.zero,new Vector3(.12f,.15f,.65f),new Color(.18f,.23f,.25f),gun,false);world.Box("Stock",new Vector3(0,-.01f,-.3f),new Vector3(.13f,.2f,.3f),HarborWorld.Wood,gun,false);world.Box("Barrel",new Vector3(0,.04f,.6f),new Vector3(.055f,.055f,.65f),Color.black,gun,false);world.Box("Magazine",new Vector3(0,-.15f,0),new Vector3(.08f,.24f,.15f),Color.black,gun,false);gun.gameObject.SetActive(false);line=new GameObject("Fishing line").AddComponent<LineRenderer>();line.positionCount=22;line.startWidth=.012f;line.endWidth=.009f;line.material=new Material(Shader.Find("Sprites/Default"));line.startColor=line.endColor=new Color(.85f,.92f,.85f,.8f);line.enabled=false;}
  public void Notice(string s){notification=s;notifyUntil=Time.unscaledTime+4;}
  void Update(){gifts.Tick(Time.unscaledDeltaTime);UpdateVisuals();if(Input.GetKeyDown(KeyCode.Tab)||Input.GetKeyDown(KeyCode.F1))ui.panel=!ui.panel;if(Input.GetKeyDown(KeyCode.Escape))ui.panel=true;Cursor.lockState=ui.panel||dead?CursorLockMode.None:CursorLockMode.Locked;Cursor.visible=ui.panel||dead;
   if(!dead){if(!ui.panel&&!testing){InputPlayer();}MovePlayer();TickFishing();fullness=Mathf.Max(0,fullness-Time.deltaTime*.035f);statusTick+=Time.deltaTime;if(statusTick>=1){statusTick=0;if(gifts.Has("status/poison"))Damage(2);if(gifts.Has("status/ignite"))Damage(3);if(fullness<=0)Damage(1);}}
   else if(Input.GetKeyDown(KeyCode.Return))Respawn();
   float throttle=driving&&!ui.panel&&!testing?Input.GetAxisRaw("Vertical"):0;float turn=driving&&!ui.panel&&!testing?Input.GetAxisRaw("Horizontal"):0;if(gifts.Has("controls/reverse")){throttle=-throttle;turn=-turn;}if(gifts.Has("player/freeze")){throttle=0;turn=0;}world.TickBoat(throttle,turn,driving,boatSpeed);if(driving){body.enabled=false;body.transform.position=world.boat.TransformPoint(new Vector3(0,.85f,-.5f));}saveTick+=Time.unscaledDeltaTime;if(saveTick>30){saveTick=0;Save();}}
  void InputPlayer(){yaw+=Input.GetAxis("Mouse X")*2;pitch=Mathf.Clamp(pitch-Input.GetAxis("Mouse Y")*2,-78,78);if(Input.GetKeyDown(KeyCode.Alpha1))SetTool(0);if(Input.GetKeyDown(KeyCode.Alpha2))SetTool(1);if(Input.GetKeyDown(KeyCode.Alpha3))SetTool(2);if(Input.GetKeyDown(KeyCode.Space)&&body.isGrounded&&!gifts.Has("player/freeze")&&!driving)vertical=7*gifts.Value("movement/super_jump")*gifts.Value("movement/weak_jump");if(Input.GetMouseButtonDown(0)){if(tool==0)CastOrHook();else if(tool==1)Shoot();else if(held!=null)Eat();}if(Input.GetMouseButtonDown(1)&&fishing!=FishingState.Idle)CancelFishing("已收回浮漂");if(Input.GetKeyDown(KeyCode.E))Interact();if(Input.GetKeyDown(KeyCode.R)&&tool==1){if(coins>=5){coins-=5;ammo=12;Notice("花费 5 金币补充弹药");}else Notice("金币不足");}if(Input.GetKeyDown(KeyCode.F))Melee();if(Input.GetKeyDown(KeyCode.G))Yeet(12);}
  void MovePlayer(){bool crouch=gifts.Has("controls/force_crouch")||(!ui.panel&&Input.GetKey(KeyCode.LeftControl));cam.transform.localPosition=Vector3.Lerp(cam.transform.localPosition,new Vector3(0,crouch?1.02f:1.62f,0),Time.deltaTime*9);body.height=crouch?1.15f:1.8f;body.center=new Vector3(0,body.height/2,0);body.transform.rotation=Quaternion.Euler(0,yaw,0);cam.transform.localRotation=Quaternion.Euler(pitch,0,0);if(driving)return;body.enabled=true;var input=testing?automationMove:!ui.panel?new Vector3(Input.GetAxisRaw("Horizontal"),0,Input.GetAxisRaw("Vertical")):Vector3.zero;if(gifts.Has("controls/reverse"))input=-input;if(gifts.Has("player/freeze")){input=Vector3.zero;impulse=Vector3.zero;vertical=0;}else{if(body.isGrounded&&vertical<0)vertical=-2;vertical-=18*Time.deltaTime;}float speed=(!ui.panel&&Input.GetKey(KeyCode.LeftShift)?7:4)*gifts.Value("movement/speed_boost")*gifts.Value("movement/slow")*(crouch?.45f:1);var move=body.transform.TransformDirection(Vector3.ClampMagnitude(input,1))*speed+Vector3.up*vertical+impulse;body.Move(move*Time.deltaTime);impulse=Vector3.Lerp(impulse,Vector3.zero,Time.deltaTime*2);if(body.transform.position.y<-.6f){vertical=0;var p=body.transform.position;p.y=-.55f;Teleport(p);if(Time.frameCount%60==0)Damage(4);Notice("落水了！靠近岸边，或使用回到码头礼物");}if(body.transform.position.y< -20)Respawn();}
  void UpdateVisuals(){bool sunset=gifts.Has("visual/sunset");world.sky.SetFloat("_Sunset",sunset?1:0);world.sun.color=sunset?new Color(1,.57f,.28f):new Color(1,.96f,.85f);world.sun.intensity=sunset?.8f:1.25f;world.sun.transform.rotation=Quaternion.Euler(sunset?9:42,-35,0);cam.backgroundColor=sunset?new Color(.55f,.3f,.3f):new Color(.55f,.75f,.83f);RenderSettings.fogColor=cam.backgroundColor;RenderSettings.fogDensity=gifts.Has("visual/deep_fog")?Mathf.Clamp(gifts.Value("visual/deep_fog"),.01f,.15f):.0025f;rod.localRotation=Quaternion.Euler(fishing==FishingState.Reeling?-12+Mathf.Sin(Time.time*12)*4:Mathf.Sin(Time.time)*.5f,0,0);gun.localRotation=Quaternion.Lerp(gun.localRotation,Quaternion.identity,Time.deltaTime*9);if(floatBobber&&line.enabled){var from=rod.TransformPoint(new Vector3(0,.6f,1.9f));for(int i=0;i<22;i++){float t=i/21f;var p=Vector3.Lerp(from,floatBobber.position,t);p.y-=Mathf.Sin(t*Mathf.PI)*.7f;line.SetPosition(i,p);}floatBobber.position=new Vector3(floatBobber.position.x,-.18f+Mathf.Sin(Time.time*(fishing==FishingState.Waiting?2:14))*.06f,floatBobber.position.z);}}
  public void SetTool(int n){tool=Mathf.Clamp(n,0,2);rod.gameObject.SetActive(tool==0);gun.gameObject.SetActive(tool==1);if(heldVisual)heldVisual.gameObject.SetActive(tool==2);if(tool!=0&&fishing!=FishingState.Idle)CancelFishing("已收回鱼竿");}
  public bool CastAt(Vector3 target){if(fishing!=FishingState.Idle||dead)return false;if(bait<=0){Notice("鱼饵用完了，去鱼市补充或触发补饵礼物");return false;}if(target.y>.2f){Notice("请朝海面抛竿");return false;}bait--;fishing=FishingState.Waiting;float wait=UnityEngine.Random.Range(4f,8f);ConsumeBite(ref wait);biteAt=Time.time+wait;floatBobber=world.Shape("Bobber",PrimitiveType.Sphere,new Vector3(target.x,-.18f,target.z),new Vector3(.18f,.3f,.18f),new Color(1,.3f,.2f),null,false).transform;line.enabled=true;tension=0;lineProgress=0;Sound(castSound);Notice("浮漂入水，等待咬钩。右键收回");return true;}
  public void CastOrHook(){if(fishing==FishingState.Idle){var forward=Vector3.ProjectOnPlane(cam.transform.forward,Vector3.up).normalized;var p=cam.transform.position+forward*15;p.y=-.2f;foreach(var island in world.islands)if(Vector2.Distance(new(p.x,p.z),new(island.x,island.z))<23){Notice("前方是陆地，请到码头边朝海面抛竿");return;}CastAt(p);}else if(fishing==FishingState.Biting){fishing=FishingState.Reeling;Notice("上钩了！按住左键收线，松开降低张力");}else if(fishing==FishingState.Waiting)CancelFishing("太早收线，鱼还没咬钩");}
  void TickFishing(){if(fishing==FishingState.Waiting&&Time.time>=biteAt){fishing=FishingState.Biting;biteDeadline=Time.time+3.5f;Sound(pop);Notice("咬钩！点击左键提竿！");}if(fishing==FishingState.Biting&&Time.time>biteDeadline)CancelFishing("错过咬钩时机");if(fishing==FishingState.Reeling&&!testing){bool pulling=!ui.panel&&Input.GetMouseButton(0);ReelStep(pulling,Time.deltaTime);}}
  public void ReelStep(bool pulling,float dt){if(fishing!=FishingState.Reeling)return;float speed=gifts.Value("fishing/fast_reel")*gifts.Value("fishing/slow_reel");lineProgress=Mathf.Clamp01(lineProgress+dt*(pulling?.18f*speed:-.025f));tension=Mathf.Clamp01(tension+dt*(pulling?.19f*(lineGuard>0?.3f:1):-.48f));if(tension>=1){if(lineGuard>0){lineGuard--;tension=.3f;}else CancelFishing("鱼线断了！试试间歇收线");}if(lineProgress>=1)LandFish();}
  public void CancelFishing(string reason){fishing=FishingState.Idle;if(floatBobber)Destroy(floatBobber.gameObject);floatBobber=null;line.enabled=false;Notice(reason);}
  public void LandFish(){var c=MakeCatch();if(nextDrip>0){c.drip=true;nextDrip--;}if(nextHeavy>0){c.weight*=nextWeight;nextHeavy--;}c.price=Mathf.RoundToInt(c.weight*12*(c.drip?3:1));bag.Add(c);held=c;landed++;ShowHeld();CancelFishing("钓到了 "+c.species+" · "+c.weight.ToString("0.00")+" kg！");Sound(pop);Save();}
  CatchData MakeCatch()=>new(){species=species[UnityEngine.Random.Range(0,species.Length)],weight=UnityEngine.Random.Range(.5f,4f),price=20};
  public void ShowHeld(){if(heldVisual)Destroy(heldVisual.gameObject);if(held!=null){heldVisual=world.Fish(new Vector3(-.35f,-.3f,.9f),.5f,held.cooked?new Color(.65f,.3f,.12f):new Color(.35f,.65f,.68f),held.drip);heldVisual.SetParent(cam.transform,false);heldVisual.localPosition=new Vector3(-.35f,-.3f,.9f);heldVisual.localRotation=Quaternion.Euler(0,90,0);heldVisual.gameObject.SetActive(tool==2);}}
  public int Sell(){if(bag.Count==0){Notice("背包里还没有鱼");return 0;}int sum=0;foreach(var c in bag)sum+=c.price;if(nextSale>0){sum=Mathf.RoundToInt(sum*nextPayout);nextSale--;}coins+=sum;bag.Clear();held=null;ShowHeld();Notice("售出鱼获，获得 "+sum+" 金币");Save();return sum;}
  public void Cook(){if(held==null){Notice("先钓一条鱼或拾取鱼获");return;}if(held.cooked){Notice("这条鱼已经烤熟了");return;}held.cooked=true;held.price=Mathf.RoundToInt(held.price*1.5f);ShowHeld();Notice("香喷喷的烤鱼！按 3 手持，左键食用");}
  public void Eat(){if(held==null)return;fullness=Mathf.Min(100,fullness+(held.cooked?40:15));health=Mathf.Min(100,health+(held.cooked?15:0));bag.Remove(held);held=bag.Count>0?bag[bag.Count-1]:null;ShowHeld();Notice("吃掉了鱼，饱食度恢复");}
  public void Interact(){if(driving){driving=false;Teleport(world.boat.position-world.boat.right*2.7f+Vector3.up*1.2f);Notice("已离开驾驶位");return;}var pos=body.transform.position;WorldEntity nearest=null;float best=3.8f;foreach(var e in entities){if(!e||e.kind==EntityKind.Boss||e.kind==EntityKind.Bird||e.kind==EntityKind.Dynamite)continue;float d=Vector3.Distance(pos,e.transform.position);if(d<best){nearest=e;best=d;}}if(nearest){Pickup(nearest);return;}if(Vector3.Distance(pos,world.shop.position)<5){Sell();return;}if(Vector3.Distance(pos,world.fire.position)<4){Cook();return;}if(Vector3.Distance(pos,world.boat.position)<6){driving=true;CancelFishing("掌舵中：W/S 前后，A/D 转向，E 下船");return;}Notice("靠近鱼市、营火、小船或地面物品后按 E");}
  public void Pickup(WorldEntity e){if(e.kind==EntityKind.Fish){var c=e.catchData??MakeCatch();bag.Add(c);held=c;ShowHeld();Notice("拾取了 "+c.species);}else if(e.kind==EntityKind.Tool){SetTool(e.toolIndex);Notice("拾回工具");}else{bait+=3;ammo=12;fullness=Mathf.Min(100,fullness+10);Notice("物资补给：鱼饵 +3，弹药装满");}entities.Remove(e);Destroy(e.gameObject);}
  public void Damage(float amount){if(dead)return;health=Mathf.Max(0,health-amount);if(health<=0){dead=true;driving=false;CancelFishing("倒地了。按 Enter 返回码头");gifts.Clear();ui.panel=true;}}
  public void Respawn(){dead=false;health=100;fullness=80;vertical=0;impulse=Vector3.zero;driving=false;gifts.Clear();Teleport(spawn);Notice("已返回码头，鱼获和金币保留");}
  public void Teleport(Vector3 p){bool was=body.enabled;body.enabled=false;body.transform.position=p;body.enabled=was&&!driving;vertical=0;}
  public void Shoot(){if(Time.time<shotAt||dead)return;if(ammo<=0){Notice("弹匣为空，R 花费 5 金币补弹");return;}shotAt=Time.time+.18f;ammo--;shotCount++;float spread=.015f*gifts.Value("weapon/max_spread")*gifts.Value("weapon/steady_aim");lastShotDirection=(cam.transform.forward+UnityEngine.Random.insideUnitSphere*spread).normalized;var start=cam.transform.position;var end=start+lastShotDirection*100;if(Physics.Raycast(start,lastShotDirection,out var hit,100)){end=hit.point;var e=hit.collider.GetComponentInParent<WorldEntity>();if(e)e.Hit(25*gifts.Value("combat/damage_boost"));}var tracer=new GameObject("Tracer").AddComponent<LineRenderer>();tracer.material=line.material;tracer.startColor=tracer.endColor=HarborWorld.Gold;tracer.startWidth=.025f;tracer.endWidth=.01f;tracer.positionCount=2;tracer.SetPositions(new[]{gun.TransformPoint(new Vector3(0,.04f,.9f)),end});Destroy(tracer.gameObject,.08f);float recoil=1.2f*gifts.Value("weapon/max_recoil")*gifts.Value("weapon/steady_aim");pitch=Mathf.Clamp(pitch-recoil,-78,78);gun.localRotation=Quaternion.Euler(-recoil*4,0,0);Sound(pop);}
  void Melee(){if(Physics.SphereCast(cam.transform.position,.5f,cam.transform.forward,out var hit,3)){var e=hit.collider.GetComponentInParent<WorldEntity>();if(e)e.Hit(18*gifts.Value("combat/damage_boost"));}Sound(pop);}
  public void Yeet(float power){if(tool==2&&held!=null){var e=SpawnFish(cam.transform.position+cam.transform.forward,1,held.drip,false);e.catchData=held;bag.Remove(held);held=bag.Count>0?bag[bag.Count-1]:null;ShowHeld();e.velocity=cam.transform.forward*power+Vector3.up*4;}else{var e=SpawnEntity(EntityKind.Tool,cam.transform.position+cam.transform.forward);e.toolIndex=tool;e.velocity=cam.transform.forward*power+Vector3.up*4;SetTool(tool==0?1:0);}}
  public WorldEntity SpawnEntity(EntityKind kind,Vector3 pos){var root=world.Root(kind.ToString(),pos);var e=root.gameObject.AddComponent<WorldEntity>();e.game=this;e.kind=kind;entities.Add(e);if(kind==EntityKind.Item)world.Box("Supply crate",Vector3.zero,Vector3.one*.7f,HarborWorld.Wood,root,false);if(kind==EntityKind.Tool)world.Box("Dropped tool",Vector3.zero,new Vector3(.12f,.12f,1.4f),HarborWorld.Gold,root,false);if(kind==EntityKind.Dynamite){world.Shape("Dynamite",PrimitiveType.Cylinder,Vector3.zero,new Vector3(.25f,.4f,.25f),new Color(.8f,.15f,.12f),root,false);e.life=3;}if(kind==EntityKind.Bird){world.Shape("Body",PrimitiveType.Sphere,Vector3.zero,new Vector3(.4f,.3f,.8f),Color.white,root,false);world.Box("Wings",Vector3.zero,new Vector3(1.8f,.06f,.3f),Color.white,root,false);e.life=20;}var col=root.gameObject.AddComponent<SphereCollider>();col.radius=kind==EntityKind.Bird?.65f:.5f;return e;}
  public WorldEntity SpawnFish(Vector3 pos,float scale,bool drip,bool isBoss,string name="random"){var model=world.Fish(pos,scale,isBoss?new Color(.65f,.22f,.17f):new Color(.24f,.58f,.62f),drip);var e=model.gameObject.AddComponent<WorldEntity>();e.game=this;e.kind=isBoss?EntityKind.Boss:EntityKind.Fish;e.health=e.maxHealth=isBoss?300:20;e.catchData=MakeCatch();if(name!="random")e.catchData.species=name;e.catchData.weight*=scale;e.catchData.drip=drip;e.catchData.price=Mathf.RoundToInt(e.catchData.weight*12*(drip?3:1));var col=model.gameObject.AddComponent<SphereCollider>();col.radius=.65f*scale;entities.Add(e);if(isBoss)boss=e;return e;}
  public bool CanApply(GiftDefinition d,out string reason){reason="";if(dead){reason="倒地时请先按 Enter 复活";return false;}if(d.id=="boss/heal"&&(!boss||boss.health<=0)){reason="当前没有首领，请先召唤首领";return false;}if(d.id=="chaos/cook_held_fish"&&held==null){reason="先钓鱼或拾取一条鱼";return false;}return true;}
  public void ApplyInstant(GiftSegment s){var id=s.gift.id;float v=s.value;var forward=Vector3.ProjectOnPlane(cam.transform.forward,Vector3.up).normalized;var p=body.transform.position+forward*5+Vector3.up*1.5f;
   switch(id){case "money/add":coins+=Mathf.Clamp(Mathf.RoundToInt(v),10,10000);break;case "money/remove":coins=Mathf.Max(0,coins-Mathf.Clamp(Mathf.RoundToInt(v),10,5000));break;case "player/heal":health=Mathf.Min(100,health+Mathf.Clamp(v,1,100));break;case "player/damage":Damage(Mathf.Clamp(v,1,75));break;case "player/feed":fullness=Mathf.Min(100,fullness+Mathf.Clamp(v,1,100));break;case "player/hunger":fullness=Mathf.Max(0,fullness-Mathf.Clamp(v,1,75));break;case "status/cleanse":gifts.Remove("status/poison");gifts.Remove("status/ignite");break;case "player/return_to_spawn":driving=false;Teleport(spawn);impulse=Vector3.zero;break;case "chaos/launch":if(driving){driving=false;body.enabled=true;}vertical=Mathf.Clamp(v,8,38);break;
    case "inventory/drop_all":foreach(var c in bag.ToArray()){var e=SpawnFish(body.transform.position+UnityEngine.Random.insideUnitSphere*1.5f+Vector3.up*2,1,c.drip,false);e.catchData=c;}bag.Clear();held=null;ShowHeld();break;
    case "chaos/yeet_held_item":Yeet(Mathf.Clamp(v,5,38));break;case "chaos/cook_held_fish":Cook();break;case "chaos/random_skin":var t=tool==0?rod:tool==1?gun:heldVisual;if(t)foreach(var r in t.GetComponentsInChildren<Renderer>())r.sharedMaterial=world.Mat(UnityEngine.Random.ColorHSV(0,1,.4f,.8f,.6f,1));break;
    case "weapon/refill_ammo":ammo=12;break;case "weapon/empty_mag":ammo=0;break;case "bait/refill":bait+=Mathf.Clamp(Mathf.RoundToInt(v),1,20);break;
    case "loot/next_drip":nextDrip+=s.count;break;case "loot/next_heavy_fish":nextHeavy+=Mathf.Min(s.count,2);nextWeight=Mathf.Clamp(v,2,5);break;case "economy/next_sale_boost":nextSale+=Mathf.Min(s.count,3);nextPayout=Mathf.Clamp(v,1,3);break;case "fishing/line_guard":lineGuard+=s.count;break;
    case "fishing/quick_bite":ArmBite(s);break;case "fishing/slow_bite":nextDelay=Mathf.Clamp(v,1,3);ArmBite(s);break;
    case "birds/protect_catch":foreach(var e in entities.ToArray())if(e&&e.kind==EntityKind.Bird){entities.Remove(e);Destroy(e.gameObject);}break;case "birds/raid":for(int i=0;i<Mathf.Clamp(s.count,1,3);i++)SpawnEntity(EntityKind.Bird,p+Vector3.up*5+UnityEngine.Random.insideUnitSphere*3);break;
    case "boss/heal":boss.health=Mathf.Min(boss.maxHealth,boss.health+boss.maxHealth*Mathf.Clamp(v,5,20)/100);break;
    case "chaos/spawn_fish":case "chaos/spawn_drip_fish":case "chaos/spawn_giant_fish":case "chaos/spawn_tiny_fish":case "chaos/spawn_boss":for(int i=0;i<Mathf.Min(s.count,3);i++)SpawnFish(p+Vector3.right*i*2,id=="chaos/spawn_giant_fish"?Mathf.Clamp(v,2,5):id=="chaos/spawn_tiny_fish"?Mathf.Clamp(v,.2f,.5f):id=="chaos/spawn_boss"?4:1,id=="chaos/spawn_drip_fish",id=="chaos/spawn_boss",s.target);break;
    case "chaos/spawn_item":for(int i=0;i<Mathf.Min(s.count,3);i++)SpawnEntity(EntityKind.Item,p+Vector3.right*i);break;case "chaos/dynamite":var bomb=SpawnEntity(EntityKind.Dynamite,p);bomb.life=Mathf.Clamp(v,1,10);break;case "chaos/boat_boost":world.boatImpulse+=world.boat.forward*Mathf.Clamp(v,5,38);break;case "chaos/boat_spin":world.boatSpin+=Mathf.Clamp(v,1,8)*180;break;
    default:throw new InvalidOperationException("Unimplemented gift "+id);
   }
  }
  public string SavePath=>Path.Combine(Application.persistentDataPath,testing?"verification-save.json":"harbor-save.json");
  public void Save(){if(testing)return;try{File.WriteAllText(SavePath,JsonUtility.ToJson(new SaveData{coins=coins,bait=bait,landed=landed,bag=new List<CatchData>(bag)},true));}catch(Exception e){Debug.LogWarning("Save failed: "+e.Message);}}
  void Load(){try{if(!File.Exists(SavePath))return;var s=JsonUtility.FromJson<SaveData>(File.ReadAllText(SavePath));coins=Mathf.Max(0,s.coins);bait=Mathf.Max(0,s.bait);landed=Mathf.Max(0,s.landed);if(s.bag!=null)bag.AddRange(s.bag);held=bag.Count>0?bag[bag.Count-1]:null;ShowHeld();}catch(Exception e){Debug.LogWarning("Load failed: "+e.Message);}}
  void OnApplicationQuit(){Save();gifts.Clear();}void OnDestroy(){if(gifts!=null)gifts.Clear();if(Instance==this)Instance=null;}
 }
